          .set({ progress: decision.patch, updatedAt: now }, { merge: true })
          .then(() => {
            stats.deactivated += 1;
            for (const r of decision.reasons) {
              stats.byReason[r] = (stats.byReason[r] ?? 0) + 1;
            }
          })
          .catch((e) => {
            stats.errors += 1;
            console.error('premiumExpiryCron: write failed', doc.id, e);
          }),
      );
